package cn.shixu.app.test;

import android.app.*;
import android.content.*;
import android.media.MediaPlayer;
import android.os.*;
import android.service.notification.StatusBarNotification;
import cn.shixu.app.*;
import java.time.*;
import java.util.*;

public final class AlertInstrumentation extends SmokeInstrumentation {
    Context c;final List<Long> ids=new ArrayList<>();
    Notification notification(long id){for(StatusBarNotification n:c.getSystemService(NotificationManager.class).getActiveNotifications())if(n.getId()==(int)id)return n.getNotification();return null;}
    boolean waitAlert(long id,boolean expected,int seconds){long until=SystemClock.elapsedRealtime()+seconds*1000L;do{if(ReminderAlertService.isAlerting(id)==expected)return true;SystemClock.sleep(120);}while(SystemClock.elapsedRealtime()<until);return false;}
    void options(boolean sound,boolean vibration,int seconds){c.getSharedPreferences("settings",0).edit().putBoolean("alert_sound",sound).putBoolean("alert_vibration",vibration).putInt("alert_seconds",seconds).commit();}
    Task task(int seconds)throws Exception{Task t=new Task();LocalDateTime now=LocalDateTime.now().withNano(0).plusSeconds(seconds);t.title="自动测试持续提醒"+ids.size();t.date=now.toLocalDate().toString();t.time=now.toLocalTime().toString();t.remind=true;t.lead=0;try(Store store=new Store(c)){store.save(t);}ids.add(t.id);return t;}
    Task load(long id){try(Store store=new Store(c)){return store.find(id);}}
    void show(Task t){Reminders.notify(c,load(t.id));check(waitAlert(t.id,true,5),"Continuous alert starts");pause();}
    void stop(Task t)throws Exception{Notification n=notification(t.id);check(n!=null&&n.actions.length==3,"Ringing notification has complete, snooze and stop");n.actions[2].actionIntent.send();check(waitAlert(t.id,false,3),"Stop action ends alert");pause();}
    Object player()throws Exception{java.lang.reflect.Field f=ReminderAlertService.class.getDeclaredField("active");f.setAccessible(true);Object service=f.get(null);if(service==null)return null;java.lang.reflect.Field p=ReminderAlertService.class.getDeclaredField("player");p.setAccessible(true);return p.get(service);}
    @Override public void onStart(){c=getTargetContext();Bundle result=new Bundle();int outcome=Activity.RESULT_OK;SharedPreferences prefs=c.getSharedPreferences("settings",0);Map<String,?> old=prefs.getAll();String[] keys={"alert_sound","alert_vibration","alert_vibration_level","alert_seconds"};try{
        SharedPreferences.Editor reset=prefs.edit();for(String key:keys)reset.remove(key);reset.commit();
        check(!ReminderAlertService.sound(c)&&ReminderAlertService.vibration(c),"Default sound off and vibration on");check(ReminderAlertService.seconds(c)==30,"Default duration is thirty seconds");
        NotificationManager channels=c.getSystemService(NotificationManager.class);channels.createNotificationChannel(new NotificationChannel("shixu_reminders_v1","待办与日程提醒",NotificationManager.IMPORTANCE_HIGH));
        startActivitySync(new Intent(c,MainActivity.class).setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitForIdleSync();check(await("事项清单"),"Home ready before settings");check(channels.getNotificationChannel("shixu_reminders_v1")==null,"Upgrade removes unused legacy notification channel");check("事项提醒".contentEquals(channels.getNotificationChannel("shixu_continuous_alerts_v1").getName()),"Live channel is renamed without replacing its ID");click("设置");
        for(int n=0;n<8&&!has("提醒时响铃");n++){for(android.view.accessibility.AccessibilityNodeInfo node:nodes())if("android.widget.ScrollView".contentEquals(node.getClassName())){node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_SCROLL_FORWARD);break;}pause();}
        check(has("弹窗消息始终保留（系统横幅）")&&has("提醒时响铃")&&has("提醒时振动")&&!has("振动强度"),"Settings exposes independent controls and fixed popup message");
        click("提醒时响铃");check(ReminderAlertService.sound(c)&&ReminderAlertService.vibration(c),"Sound toggle does not change vibration");click("提醒时振动");check(ReminderAlertService.sound(c)&&!ReminderAlertService.vibration(c),"Vibration toggle does not change sound");check(!has("振动强度"),"Vibration off hides entire intensity section");click("提醒时响铃");click("提醒时振动");check(!has("振动强度"),"Vibration on no longer offers unsupported strength levels");
        for(android.view.accessibility.AccessibilityNodeInfo node:nodes())if("android.widget.ScrollView".contentEquals(node.getClassName())){node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_SCROLL_FORWARD);break;}pause();
        for(int n:new int[]{2,5,15}){clickDescription("选择提醒持续时间");check(!has("60秒"),"Removed sixty-second option is absent");click(n+"秒");check(ReminderAlertService.seconds(c)==n,"Duration dropdown persists "+n+" seconds");}clickDescription("选择提醒持续时间");click("30秒");check(ReminderAlertService.seconds(c)==30,"Duration can return to default");
        capture(c,"alert-settings.png");click("完成");
        options(false,false,15);Task silent=task(1800);Reminders.notify(c,silent);pause();check(!ReminderAlertService.isAlerting(silent.id),"Both outputs off starts no service");Notification quiet=notification(silent.id);check(quiet!=null&&quiet.actions.length==2,"Message remains with both outputs off");NotificationChannel channel=c.getSystemService(NotificationManager.class).getNotificationChannel(quiet.getChannelId());check(channel.getImportance()==NotificationManager.IMPORTANCE_HIGH&&channel.getSound()==null&&!channel.shouldVibrate(),"Default popup channel is high importance with no unwanted system sound or vibration");
        options(false,true,15);Task alarm=task(3);Reminders.schedule(c,alarm);getUiAutomation().executeShellCommand("input keyevent 3").close();check(waitAlert(alarm.id,true,10),"Real scheduled alarm starts continuous foreground alert in background");pause();check(player()==null,"Vibration-only does not create audio player");stop(alarm);check(notification(alarm.id)!=null&&notification(alarm.id).actions.length==2&&!load(alarm.id).done,"Stop retains normal actionable notification and does not complete task");
        options(false,true,2);Task auto=task(1800);long began=SystemClock.elapsedRealtime();show(auto);long delivered=notification(auto.id).extras.getLong(Reminders.DELIVERED_AT);check(delivered>0,"Actual delivery time recorded before continuous alert ends");check(waitAlert(auto.id,false,5),"Two-second alert automatically ends");check(SystemClock.elapsedRealtime()-began>=1700,"Alert is not stopped immediately");pause();check(notification(auto.id)!=null&&notification(auto.id).actions.length==2,"Auto stop retains notification without stop action");check(notification(auto.id).when==delivered&&notification(auto.id).extras.getLong(Reminders.DELIVERED_AT)==delivered,"Auto stop preserves original display and delivery time");
        options(false,true,5);Task five=task(1800);long fiveStart=SystemClock.elapsedRealtime();show(five);check(waitAlert(five.id,false,8),"Five-second alert automatically ends");check(SystemClock.elapsedRealtime()-fiveStart>=4500,"Five-second duration is respected");
        options(true,false,15);Task audio=task(1800);show(audio);long until=SystemClock.elapsedRealtime()+4000;boolean playing=false;while(SystemClock.elapsedRealtime()<until){Object p=player();if(p instanceof MediaPlayer&&((MediaPlayer)p).isPlaying()){playing=true;break;}SystemClock.sleep(120);}check(playing,"Sound-only plays looping alarm audio");stop(audio);
        options(true,true,30);Task snooze=task(1800);show(snooze);long before=System.currentTimeMillis();notification(snooze.id).actions[1].actionIntent.send();check(waitAlert(snooze.id,false,3),"Snooze immediately stops active alert");pause();check(load(snooze.id).snoozeUntil>=before+600000,"Snooze persists new trigger ten minutes ahead");check(notification(snooze.id)==null,"Snooze removes current notification");
        Task complete=task(1800);show(complete);notification(complete.id).actions[0].actionIntent.send();check(waitAlert(complete.id,false,3),"Complete immediately stops active alert");pause();check(load(complete.id).done&&notification(complete.id)==null,"Complete persists completion and removes notification");
        Task first=task(1800);show(first);Notification oldAlert=notification(first.id);Task second=task(1800);show(second);check(!ReminderAlertService.isAlerting(first.id)&&notification(first.id).actions.length==2,"Overlapping reminders preserve older message without overlapping output");oldAlert.actions[2].actionIntent.send();pause();check(ReminderAlertService.isAlerting(second.id),"Older stop action cannot stop newer reminder");notification(second.id).deleteIntent.send();check(waitAlert(second.id,false,3),"Dismiss stops continuous output");pause();check(notification(second.id)==null,"Dismiss does not recreate the dismissed notification");
        result.putString("result","PASS: "+checks+" defaults, independent settings, real alarm, timed stop, audio playback, completion, snooze and overlapping alert checks");
    }catch(Throwable e){outcome=Activity.RESULT_CANCELED;result.putString("error",android.util.Log.getStackTraceString(e));}finally{
        for(long id:ids)try(Store store=new Store(c)){Task t=store.find(id);if(t!=null){Reminders.cancel(c,t);store.delete(id);}}
        SystemClock.sleep(400);SharedPreferences.Editor restore=prefs.edit();for(String key:keys){Object value=old.get(key);if(value instanceof Boolean)restore.putBoolean(key,(Boolean)value);else if(value instanceof Integer)restore.putInt(key,(Integer)value);else restore.remove(key);}restore.commit();
    }finish(outcome,result);}
}
